document.documentElement.classList.add('js');
const wa = message => 'https://wa.me/2349163351767?text='+encodeURIComponent(message);
document.querySelectorAll('[data-whatsapp]').forEach(a=>{a.href=wa(a.dataset.whatsapp);a.target='_blank';a.rel='noopener noreferrer'});
const observer = new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));
const header=document.querySelector('header');addEventListener('scroll',()=>header.classList.toggle('fixed',scrollY>100),{passive:true});
const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const opened=nav.classList.toggle('open');menu.setAttribute('aria-expanded',opened);menu.setAttribute('aria-label',opened?'Close menu':'Open menu');menu.textContent=opened?'×':'☰'});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='☰'}));
const dateString=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');const checkin=document.querySelector('#checkin'),checkout=document.querySelector('#checkout');checkin.min=dateString(new Date());checkin.addEventListener('change',()=>{if(!checkin.value)return;const d=new Date(checkin.value+'T12:00:00');d.setDate(d.getDate()+1);checkout.min=dateString(d);if(checkout.value<=checkin.value)checkout.value=checkout.min;checkout.setCustomValidity('')});
document.querySelector('#booking-form').addEventListener('submit',e=>{e.preventDefault();if(checkout.value<=checkin.value){checkout.setCustomValidity('Choose a check-out date after check-in.');checkout.reportValidity();return}const message=`Hello Hotel DelaCruxe, I would like to enquire about a reservation.\nCheck-in: ${checkin.value}\nCheck-out: ${checkout.value}\nGuests: ${document.querySelector('#guests').value}\nRoom preference: ${document.querySelector('#preference').value}\nName: ${document.querySelector("#guest-name").value.trim()}\nArrival time (WAT): ${document.querySelector("#arrival").value}\nRooms: ${document.querySelector("#room-count").value}\nSpecial requests: ${document.querySelector("#requests").value.trim() || "None"}\nPlease confirm availability, the room category, total price and your booking terms. Thank you.`;window.open(wa(message),'_blank','noopener,noreferrer')});
const modal=document.querySelector('#lightbox');document.querySelectorAll('[data-photo]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#lightbox-img').src=b.dataset.photo;document.querySelector('#lightbox-img').alt=b.dataset.caption;document.querySelector('#lightbox-caption').textContent=b.dataset.caption;modal.showModal()}));document.querySelector('#close-lightbox').addEventListener('click',()=>modal.close());modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});document.querySelector('#year').textContent=new Date().getFullYear();

function updateSummary(){const days=Math.round((new Date(checkout.value)-new Date(checkin.value))/86400000);document.querySelector('#stay-summary').textContent=days>0?`${days} night${days===1?'':'s'} · ${document.querySelector('#guests').value} · ${document.querySelector('#room-count').value} room(s)`:'Choose your dates to plan your stay.'}
document.querySelector('#booking-form').addEventListener('input',updateSummary);updateSummary();

const reduced=matchMedia('(prefers-reduced-motion: reduce)');let ticking=false;
const scenes=[...document.querySelectorAll('.experience-image,.gallery-item.tall')];
function scrollScene(){header.classList.toggle('fixed',scrollY>100);const total=document.documentElement.scrollHeight-innerHeight;document.querySelector('.scroll-progress').style.transform=`scaleX(${total>0?scrollY/total:0})`;if(!reduced.matches){const hero=document.querySelector('.hero');const progress=Math.min(scrollY/hero.offsetHeight,1);document.querySelector('.hero-image').style.transform=`translateY(${progress*26}px) scale(1.045)`;scenes.forEach(el=>{const rect=el.getBoundingClientRect();const offset=Math.max(-18,Math.min(18,(innerHeight/2-rect.top-rect.height/2)*.045));el.querySelector('img').style.transform=`translateY(${offset}px) scale(1.07)`})}ticking=false}
addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(scrollScene);ticking=true}},{passive:true});addEventListener('resize',scrollScene);scrollScene();
const reservation=document.querySelector('#reservation');const sourceForm=document.querySelector('#booking-form');const overlayForm=sourceForm.cloneNode(true);overlayForm.id='overlay-form';overlayForm.className='';overlayForm.querySelectorAll('[id]').forEach(el=>el.id='overlay-'+el.id);document.querySelector('#reservation-fields').append(overlayForm);
const field=id=>overlayForm.querySelector('#overlay-'+id);let bookingTrigger=null;let savedScroll=0;
function openReservation(trigger,index){bookingTrigger=trigger;savedScroll=scrollY;if(index!==undefined)field('preference').selectedIndex=index+1;updatePreview();reservation.showModal();document.body.style.overflow='hidden';}
function updatePreview(){const index=field('preference').selectedIndex;const images=['room2.webp','room2.webp','room0.webp','room1.webp'];document.querySelector('#selected-photo').src='assets/'+images[index];document.querySelector('#selected-room').textContent=index?field('preference').selectedOptions[0].textContent.split(' (')[0]:'Your DelaCruxe stay';}
document.querySelectorAll('[data-room]').forEach((a,i)=>{a.href='#reservation';a.removeAttribute('target');a.setAttribute('aria-haspopup','dialog');a.addEventListener('click',e=>{e.preventDefault();openReservation(a,i)})});
document.querySelectorAll('header a[href="#booking"],.floating-wa').forEach(a=>{a.href='#reservation';a.removeAttribute('target');a.setAttribute('aria-haspopup','dialog');a.addEventListener('click',e=>{e.preventDefault();openReservation(a)})});
reservation.querySelector('.reservation-close').addEventListener('click',()=>reservation.close());reservation.addEventListener('click',e=>{if(e.target===reservation){const r=reservation.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)reservation.close()}});reservation.addEventListener('close',()=>{document.body.style.overflow='';bookingTrigger?.focus({preventScroll:true})});
function overlaySummary(){const days=Math.round((new Date(field('checkout').value)-new Date(field('checkin').value))/86400000);field('stay-summary').textContent=days>0?`${days} night${days===1?'':'s'} · ${field('guests').value} · ${field('room-count').value} room(s)`:'Choose your dates to plan your stay.';updatePreview()}
field('checkin').addEventListener('change',()=>{if(!field('checkin').value)return;const d=new Date(field('checkin').value+'T12:00:00');d.setDate(d.getDate()+1);field('checkout').min=dateString(d);if(field('checkout').value<=field('checkin').value)field('checkout').value=field('checkout').min;field('checkout').setCustomValidity('');overlaySummary()});field('checkout').addEventListener('input',()=>field('checkout').setCustomValidity(''));overlayForm.addEventListener('input',overlaySummary);
overlayForm.addEventListener('submit',e=>{e.preventDefault();if(field('checkout').value<=field('checkin').value){field('checkout').setCustomValidity('Choose a check-out date after check-in.');field('checkout').reportValidity();return}const message=`Hello Hotel DelaCruxe, I would like to enquire about a reservation.\nName: ${field('guest-name').value.trim()}\nRoom preference: ${field('preference').value}\nCheck-in: ${field('checkin').value}\nCheck-out: ${field('checkout').value}\nArrival time (WAT): ${field('arrival').value}\nGuests: ${field('guests').value}\nRooms: ${field('room-count').value}\nSpecial requests: ${field('requests').value.trim()||'None'}\nPlease confirm availability, total price and booking terms. Thank you.`;window.open(wa(message),'_blank','noopener,noreferrer')});
checkout.addEventListener('input',()=>checkout.setCustomValidity(''));
